package com.bank.hierarchy;

import java.util.logging.Logger;

// Measures the longest escalation chain via recursive DFS.
public class HierarchyDepthService {

    private static final Logger log = Logger.getLogger(HierarchyDepthService.class.getName());

    public int maxDepth(ApproverNode node) {
        // Base case: an empty branch contributes zero depth.
        if (node == null) {
            return 0;
        }
        // Recursive case: ask both escalation paths how deep they go.
        int leftDepth = maxDepth(node.getLeft());
        int rightDepth = maxDepth(node.getRight());
        // Add one for the current approver; follow the deeper path.
        return 1 + Math.max(leftDepth, rightDepth);
    }

    public int measureLongestChain(ApproverNode root) {
        int depth = maxDepth(root);
        log.info(() -> "Longest approval escalation chain depth = " + depth);
        if (depth > 4) {
            log.warning(() -> "Chain depth " + depth + " may breach approval SLA");
        }
        return depth;
    }
}
