package com.bank.hierarchy;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class HierarchyDepthDemo {

    private static final Logger log = Logger.getLogger(HierarchyDepthDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Loan Approval Chain Depth");

        // Build hierarchy:
        //            BranchManager
        //           /             \
        //     CreditOfficer     RiskHead
        //         /                   \
        //   JuniorAnalyst          RegionalVP
        //                               \
        //                            NationalHead
        ApproverNode branchManager = new ApproverNode("BranchManager");
        ApproverNode creditOfficer = new ApproverNode("CreditOfficer");
        ApproverNode riskHead = new ApproverNode("RiskHead");
        ApproverNode juniorAnalyst = new ApproverNode("JuniorAnalyst");
        ApproverNode regionalVP = new ApproverNode("RegionalVP");
        ApproverNode nationalHead = new ApproverNode("NationalHead");

        branchManager.setLeft(creditOfficer);
        branchManager.setRight(riskHead);
        creditOfficer.setLeft(juniorAnalyst);
        riskHead.setRight(regionalVP);
        regionalVP.setRight(nationalHead);

        new HierarchyDepthService().measureLongestChain(branchManager);
    }
}
